"clientScript": {
"css": "\na:focus-visible, button:focus-visible { outline: 2px solid var(--147036ff-9b8a-4688-b8ff-4db51295fb84); outline-offset: 3px; }\n\n.mq-hang { --drop: 0px; color: var(--d253d0b9-f0e0-4322-aa19-e8e8fa6c9499); transform: translateY(var(--drop)); }\n.mq-hang::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 4px; background-color: var(--2333a099-c4ee-4345-995b-45bad0acb477); opacity: 0; }\n.mq-hang-name { color: var(--3777025d-c4f6-4fb0-b2fb-3190383c9775); }\n.mq-hang[data-kept=\"true\"] .mq-hang-fate { color: var(--2333a099-c4ee-4345-995b-45bad0acb477); }\n.mq-hang:hover { translate: 0 2px; color: var(--3777025d-c4f6-4fb0-b2fb-3190383c9775); }\n.mq-hang:active { translate: 0 1px; }\n.mq-hang[aria-selected=\"true\"] { --drop: 12px; color: var(--3777025d-c4f6-4fb0-b2fb-3190383c9775); }\n.mq-hang[aria-selected=\"true\"] .mq-hang-name { color: var(--a26a5991-5a44-439c-8a25-1356a27b9467); }\n.mq-hang[aria-selected=\"true\"]::after { opacity: 1; }\n/* Without script every reason is listed under its head's name and the kept head is the print.\n   Once the client script marks the root ready, the reasons share one cell (so a pick never changes\n   the height) and only the picked one shows. */\n.mq-whys { row-gap: 24px; }\n:scope[data-ready=\"true\"] .mq-whys { row-gap: 0; }\n:scope[data-ready=\"true\"] .mq-why { grid-area: 1 / 1; }\n:scope[data-ready=\"true\"] .mq-why[data-active=\"false\"] { visibility: hidden; }\n:scope[data-ready=\"true\"] .mq-why-name { display: none; }\n.mq-shot { opacity: 0; }\n.mq-shot[data-active=\"true\"] { opacity: 1; }\n@media (prefers-reduced-motion: no-preference) {\n  :scope[data-settled=\"true\"] .mq-hang { transition: transform 280ms cubic-bezier(0.16, 1, 0.3, 1), translate 160ms cubic-bezier(0.16, 1, 0.3, 1), color 160ms cubic-bezier(0.16, 1, 0.3, 1); }\n  :scope[data-settled=\"true\"] .mq-hang::after, :scope[data-settled=\"true\"] .mq-shot { transition: opacity 280ms cubic-bezier(0.16, 1, 0.3, 1); }\n}\n",
"js": "\nconst live = typeof window !== \"undefined\";\nconst tabs = Array.from(this.querySelectorAll(\".mq-hang\"));\nconst whys = Array.from(this.querySelectorAll(\".mq-why\"));\nconst shots = Array.from(this.querySelectorAll(\".mq-shot\"));\nconst list = this.querySelector(\".mq-rail\");\nconst count = tabs.length;\nif (!count || !list) return;\nconst data = component_data || {};\nconst fromServer = tabs.findIndex((tab) => tab.getAttribute(\"aria-selected\") === \"true\");\nlet current = Number(data.active_index);\nif (data.active_index === undefined || data.active_index === null || !Number.isFinite(current)) current = Math.max(fromServer, 0);\ncurrent = Math.min(Math.max(Math.round(current), 0), count - 1);\n// the reasons stack and hide only once this script runs: without it every reason stays listed\nthis.dataset.ready = \"true\";\nconst paint = (index) => {\n  tabs.forEach((tab, i) => {\n    tab.setAttribute(\"aria-selected\", i === index ? \"true\" : \"false\");\n    tab.setAttribute(\"tabindex\", i === index ? \"0\" : \"-1\");\n  });\n  whys.forEach((why, i) => {\n    why.setAttribute(\"data-active\", i === index ? \"true\" : \"false\");\n    why.setAttribute(\"aria-hidden\", i === index ? \"false\" : \"true\");\n  });\n  shots.forEach((shot, i) => {\n    shot.setAttribute(\"data-active\", i === index ? \"true\" : \"false\");\n    shot.setAttribute(\"aria-hidden\", i === index ? \"false\" : \"true\");\n  });\n};\npaint(current);\nif (!live) return;\nconst settle = () => requestAnimationFrame(() => requestAnimationFrame(() => { this.dataset.settled = \"true\"; }));\nif (document.readyState === \"loading\") document.addEventListener(\"DOMContentLoaded\", settle, { once: true });\nelse settle();\n\nif (typeof this.mqOptionsCleanup === \"function\") this.mqOptionsCleanup();\nconst uid = \"mq-opt-\" + Math.random().toString(36).slice(2, 8);\nconst title = this.querySelector(\".mq-opt-title\");\nif (title) {\n  title.id = uid + \"-title\";\n  list.setAttribute(\"aria-labelledby\", title.id);\n  list.removeAttribute(\"aria-label\");\n}\ntabs.forEach((tab, i) => {\n  tab.id = uid + \"-tab-\" + i;\n  const why = whys[i];\n  if (why) {\n    why.id = uid + \"-panel-\" + i;\n    tab.setAttribute(\"aria-controls\", why.id);\n    why.setAttribute(\"aria-labelledby\", tab.id);\n  }\n});\nconst select = (index, focus) => {\n  current = (index + count) % count;\n  paint(current);\n  if (focus) tabs[current].focus();\n};\nconst onClick = (event) => {\n  const tab = event.target.closest(\".mq-hang\");\n  if (!tab) return;\n  const index = tabs.indexOf(tab);\n  if (index >= 0) select(index, false);\n};\nconst onKey = (event) => {\n  const moves = { ArrowRight: current + 1, ArrowDown: current + 1, ArrowLeft: current - 1, ArrowUp: current - 1, Home: 0, End: count - 1 };\n  if (!(event.key in moves)) return;\n  event.preventDefault();\n  select(moves[event.key], true);\n};\nlist.addEventListener(\"click\", onClick);\nlist.addEventListener(\"keydown\", onKey);\nconst cleanup = () => {\n  document.removeEventListener(\"DOMContentLoaded\", settle);\n  list.removeEventListener(\"click\", onClick);\n  list.removeEventListener(\"keydown\", onKey);\n  this.mqOptionsCleanup = null;\n};\nthis.mqOptionsCleanup = cleanup;\nreturn cleanup;\n"
},
